// Elf64 Object File identification and key structures
#define EI_MAG0 0x7f
#define ET_REL  1  // Relocatable (Input to Linker)
#define ET_EXEC 2  // Executable (Ready to Run)
#define ET_DYN  3  // Shared Object (Dynamic Library)

typedef uint64_t Elf64_Addr;

// Section Header Table (SHT) entry defines sections (.text, .data)
// Used by static linker (ld)
typedef struct {
    uint32_t sh_name;
    uint32_t sh_type; // SHT_PROGBITS, SHT_SYMTAB, SHT_RELA
    Elf64_Addr sh_addr;
} Elf64_Shdr;

// Program Header Table (PHT) entry defines memory segments (LOAD, BSS)
// Used by dynamic loader (kernel/ld.so)
typedef struct {
    uint32_t p_type;  // PT_LOAD, PT_DYNAMIC
    uint64_t p_vaddr; // Virtual address
} Elf64_Phdr;
